insert into adaptive_topics (id, project_id, topic, state, evidence, did, saved, position) values
  ('ad0', 'it-helpdesk', 'Never ask for a password', 'Converged', '5 of 5 agree', 'Stopped asking 3 people · 6 min saved', 6, 0),
  ('ad1', 'it-helpdesk', 'Hardware order limit', 'Conflict', '$500 vs $250', 'Follow-up sent to Service desk and Finance only', 0, 1),
  ('ad2', 'it-helpdesk', 'Password reset check', 'Conflict', 'One question vs MFA push', 'Follow-up sent to Service desk and Security only', 0, 2),
