insert into decisions (id, project_id, title, note, warn, done, options, chosen, rationale, pinned, follow_up, status, position) values
  ('DEC-03', 'it-helpdesk', 'Password resets through chat', '', '', '', '[["One verification question","Service desk","Locked-out people can’t get the push half the time.",["Fastest for locked-out employees","Account-takeover risk rises"],35],["MFA push before any change","Security and risk · Legal and risk","A reset without MFA is how account takeovers start.",["Needs a fallback when the phone is lost","Needs MFA push configured for chat (A-015)"],65]]'::jsonb, 1, 'HC-007 rules out passwords; an MFA push is the only check that meets it.', 'CI-0231 v2', 'A-015 · Priya Shah · Nov 28', 'Open', 0),
  ('DEC-07', 'it-helpdesk', 'Tone wording', 'Sam kept his wording after Grace’s suggestion; both versions are with the decider.', '', '', '[["Sam’s: steps first, no apologies","Service desk"],["Grace’s: acknowledge in one line, then the steps","People"]]'::jsonb, null, '', '', '', 'Open', 1),
  ('DEC-06', 'it-helpdesk', 'After-hours escalation', 'On-call within 15 minutes · carries HC-012', 'Low support, high stakes', '', '[]'::jsonb, null, '', '', '', 'Open', 2),
  ('DEC-04', 'it-helpdesk', 'Hardware without approval', '$250, revisit in Q2 with spend data · A-014 Lena Ortiz', '', 'Decided Oct 28', '[]'::jsonb, null, '', '', '', 'Decided', 3),
  ('DEC-05', 'it-helpdesk', 'Personal devices', 'Deferred as an open question · A-017', '', 'Deferred', '[]'::jsonb, null, '', '', '', 'Deferred', 4);
